/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class AlertsUnitTest {

  @Test
  @DisplayName("Errors per minute: complete minutes of the window only, per source or for all")
  void errorRate() {
    ErrorRateWindow window = new ErrorRateWindow();
    long now = 100 * 60_000L + 30_000;
    for (int i = 0; i < 30; i++) {
      window.add("api", 99 * 60_000L + i * 1_000);
    }
    for (int i = 0; i < 10; i++) {
      window.add("api", 98 * 60_000L + i);
      window.add("ui", 98 * 60_000L + i);
    }
    window.add("api", now);
    Assertions.assertEquals(20.0, window.perMinute("api", 2, now), 0.001);
    Assertions.assertEquals(30.0, window.perMinute("api", 1, now), 0.001);
    Assertions.assertEquals(25.0, window.perMinute(null, 2, now), 0.001);
    Assertions.assertEquals(0.0, window.perMinute("api", 2, now + 10 * 60_000L), 0.001);
  }

  @Test
  @DisplayName("A webhook without http(s) URL fails, so the notice stays pending")
  void webhookUrl() {
    AlertNotification notification = new AlertNotification("a", "r", "Rule", "new-issue", "FIRING",
        "webhook", "file:///etc/passwd", "boom", "/observe/#/issues/1", Map.of());
    WebhookAlertChannel channel = new WebhookAlertChannel();
    Assertions.assertTrue(channel.accepts("webhook"));
    Assertions.assertThrows(IllegalArgumentException.class, () -> channel.deliver(notification));
  }

  @Test
  @DisplayName("The rule options are compared as written in the model")
  void optionValues() {
    Assertions.assertEquals("new-issue", AlertRules.value(Trigger.NEW_ISSUE));
    Assertions.assertEquals("collector-dropping", AlertRules.value(Trigger.COLLECTOR_DROPPING));
    Assertions.assertNull(AlertRules.value(null));
  }

  private enum Trigger {
    NEW_ISSUE, COLLECTOR_DROPPING
  }
}
